import assert from 'node:assert/strict';
import fs from 'node:fs';
import test from 'node:test';
import { BuilderBase, Collection, CustomTypes, sourceBagFromTytx, sourceBagToTytx } from '../src/index.js';

// Generated by the Python ContactBuilder contract test, not handwritten JS data.
const fixture = JSON.parse(fs.readFileSync(new URL('./fixtures/custom-types.json', import.meta.url)));
const builder = () => new BuilderBase().loadGrammar(structuredClone(fixture), { replace: true });
const contact = (b, method, record_id = '') => b.setChild(b.source, 'contact', null, { method, code: 'AB1234', record_id });

test('Python catalog loads, exposes named references and retains exact definitions', () => {
    const ct = CustomTypes.fromJSON(fixture.custom_types);
    assert.deepEqual(ct.no_pointer, { kind: 'custom', name: 'no_pointer' });
    assert.deepEqual(ct.toJSON(), fixture.custom_types);
    assert.equal(ct.validate('code', 'AB1234'), true);
    assert.throws(() => ct.validate('code', 'bad'), /code/);
    assert.throws(() => ct.validate('missing', 'bad'), /unknown custom type/);
    const exported = ct.toJSON();
    exported.code.metadata[0].pattern = '.*';
    assert.throws(() => ct.validate('code', 'bad'), /code/);
    assert.throws(() => { ct.code = String; }, TypeError);
});

test('JS registration produces the same catalog as Python', () => {
    const ct = new CustomTypes();
    ct.register('no_pointer', String, { kind: 'regex', pattern: String.raw`(?![\^=])[\s\S]*`, flags: 0 });
    ct.register('code', 'string', { kind: 'regex', pattern: '[A-Z]{2}[0-9]{4}', flags: 0 });
    ct.register('positive', 'integer', { kind: 'range', ge: 1, le: null, gt: null, lt: null });
    assert.deepEqual(ct.toJSON(), fixture.custom_types);
    assert.throws(() => ct.register('code', String, { kind: 'regex', pattern: '.*', flags: 0 }), /duplicate/);
    for (const name of ['class', '_hidden', 'bad-name', 'register', 'resolve', 'to_dict', 'toJSON']) {
        assert.throws(() => ct.register(name, String, { kind: 'regex', pattern: '.*', flags: 0 }), /name/);
    }
});

test('literal input and permissive string pointers preserve behavior', () => {
    for (const value of ['', 'details', 'multi\nline', '😀', 'inside^=', '\n=second line']) {
        for (const prefix of ['^', '=']) {
            const b = builder(); b.data.setItem('record_id', 42);
            const node = contact(b, value, `${prefix}record_id`);
            const [, attrs] = b.runtimeValues(node);
            assert.equal(attrs.method, value);
            assert.equal(attrs.record_id, 42);
        }
    }
});

test('forbidden prefixes fail during authoring without adding Source nodes', () => {
    for (const value of ['^method', '=method', '==method', '^', '=']) {
        const b = builder();
        assert.throws(() => contact(b, value), /invalid value/);
        assert.equal(b.source.getNodes().length, 0);
    }
});

test('mutated and serialized Source fails before resolution or pointer discovery', () => {
    for (const serialized of [false, true]) {
        for (const method of ['^method', '=method', '==method']) {
            const b = builder(); let node = contact(b, 'details', '^record_id');
            node.setAttr({ method });
            if (serialized) {
                b.source = sourceBagFromTytx(sourceBagToTytx(b.source), b);
                node = b.source.getNodes()[0];
            }
            for (const consume of [() => b.runtimeValues(node), () => node.pointers(), () => b.validateSource()]) {
                assert.throws(consume, /custom type/);
            }
        }
    }
});

test('optional, nested and numeric registered constraints match Python', () => {
    const b = builder();
    b.setChild(b.source, 'optional', null, {});
    b.setChild(b.source, 'optional', null, { method: null });
    b.setChild(b.source, 'codes', null, { values: ['AB1234'] });
    b.setChild(b.source, 'count', 1, {});
    assert.throws(() => b.setChild(b.source, 'codes', null, { values: ['bad'] }), /invalid value/);
    for (const value of [0, true]) assert.throws(() => b.setChild(b.source, 'count', value, {}), /invalid value/);
});

test('missing names and incompatible catalog versions fail clearly', () => {
    const doc = structuredClone(fixture);
    delete doc.custom_types.no_pointer;
    assert.throws(() => new BuilderBase().loadGrammar(doc), /unknown custom type/);
    const old = structuredClone(fixture); old.document_format.version = '1.1';
    assert.throws(() => new BuilderBase().loadGrammar(old), /version 1.2/);
});

test('catalog composition rejects conflicting definitions atomically', () => {
    const b = builder();
    const conflict = structuredClone(fixture);
    conflict.custom_types.code.metadata[0].pattern = '[0-9]+';
    assert.throws(() => b.loadGrammar(conflict), /conflicting custom type/);
    contact(b, 'details');
    const legacy = { ...structuredClone(fixture), elements: {}, abstracts: {} };
    delete legacy.custom_types;
    legacy.document_format.version = '1.1';
    const collection = new Collection(fixture).update(legacy);
    assert.equal(collection.toDocument().document_format.version, '1.2');
    b.loadGrammar(legacy);
    assert.throws(() => contact(b, '^method'), /invalid value/);
});

test('unsupported validators fail before publishing registrations', () => {
    const ct = new CustomTypes();
    for (const constraint of [
        { kind: 'regex', pattern: String.raw`\w+`, flags: 0 },
        { kind: 'regex', pattern: 'abc', flags: 2 },
        { kind: 'unknown' },
    ]) assert.throws(() => ct.register('invalid', String, constraint), /portable|Regex/);
    assert.equal(ct.invalid, undefined);
});

test('subbuilder envelope keeps the host custom constraint after transport', () => {
    class Inner extends BuilderBase { static _name = 'custom_types_inner'; }
    BuilderBase.registerBuilder(Inner);
    const doc = structuredClone(fixture);
    doc.elements.contact._meta = { subbuilder: 'custom_types_inner' };
    for (const serialized of [false, true]) {
        const b = new BuilderBase().loadGrammar(doc, { replace: true });
        let node = contact(b, 'details');
        assert(node.builder instanceof Inner);
        node.setAttr({ method: '^method' });
        if (serialized) {
            b.source = sourceBagFromTytx(sourceBagToTytx(b.source), b);
            node = b.source.getNodes()[0];
        }
        for (const consume of [() => b.runtimeValues(node), () => node.pointers(), () => b.validateSource()]) {
            assert.throws(consume, /custom type/);
        }
    }
});

test('portable regex dot and anchors keep Python LF semantics', () => {
    const ct = new CustomTypes();
    const cases = [
        ['.+', 0, '\r', true], ['.+', 0, '\u2028', true], ['.+', 0, '\u2029', true],
        ['.+', 0, '\n', false], ['.+', 16, '\n', true],
        [String.raw`a$\r`, 0, 'a\r', false], [String.raw`a$\n`, 0, 'a\n', true],
        [String.raw`a$\r`, 8, 'a\r', false], [String.raw`a$\nb`, 8, 'a\nb', true],
        [String.raw`a\n^b`, 8, 'a\nb', true], [String.raw`a\r^b`, 8, 'a\rb', false],
        ['[.$^]+', 0, '.$^', true], [String.raw`\.+`, 0, '...', true],
        ['AB[0-9]+', 0, 'AB12\n', false],
    ];
    for (const [i, [pattern, flags, value, expected]] of cases.entries()) {
        ct.register(`pattern${i}`, String, { kind: 'regex', pattern, flags });
        assert.equal(ct.resolve(`pattern${i}`).test(value), expected, JSON.stringify({ pattern, flags, value }));
    }
    for (const pattern of [String.raw`\bélan\b`, '(?i:abc)', 'a++', String.raw`(a)?\1`]) {
        assert.throws(() => ct.register('unsupported', String, { kind: 'regex', pattern, flags: 0 }), /portable/);
    }
});
